#include "SamplerTuning.h"
#include "ControlEdits.h"
static AudioBuffer<float> tuningTone(double rate,double frequency,double seconds=1,bool harmonic=false){AudioBuffer<float> out(2,(int)(rate*seconds));for(int i=0;i<out.getNumSamples();++i){double phase=2*3.14159265358979323846*frequency*i/rate;float v=(float)(.35*std::sin(phase)+(harmonic?.2*std::sin(phase*2)+.12*std::sin(phase*3):0));out.setSample(0,i,v);out.setSample(1,i,-v);}return out;}
static double tuningFrequency(const AudioBuffer<float>& audio,double rate){int start=(int)(rate*.1),last=-1,first=-1,crossings=0;for(int i=start+1;i<jmin((int)(rate*.45),audio.getNumSamples());++i)if(audio.getSample(0,i-1)<=0&&audio.getSample(0,i)>0){if(first<0)first=i;last=i;++crossings;}return crossings>1?(crossings-1)*rate/(last-first):0;}
static void testSamplerTuning(const File& root,Assets& assets){
    expect(samplerRatio(60,60,0)==1&&samplerRatio(72,60,0)==2&&samplerRatio(48,60,0)==.5,"legacy C4 sampler mapping stays exact");expect(samplerRatio(69,57,0)==2&&samplerRatio(69,69,100)>1&&samplerRatio(69,69,-100)<1,"sampler root and positive/negative fine tune use expected pitch direction");expect(samplerNoteName(48)=="C3"&&samplerNoteName(60)=="C4"&&samplerNoteName(127)=="G9","sampler labels match Piano roll scientific octave naming");
    for(auto values:{std::pair{0,-100.},std::pair{127,100.},std::pair{60,0.}})expect(validateSamplerTuning(values.first,values.second).wasOk(),"sampler tuning accepts inclusive limits");for(auto values:{std::pair{-1,0.},std::pair{128,0.},std::pair{60,100.1},std::pair{60,std::nan("")}})expect(validateSamplerTuning(values.first,values.second).failed(),"invalid sampler tuning rejects");
    auto song=emptyProject();song.tracks[7].sampleRoot=57;song.tracks[7].sampleTune=-23.5;Project loaded;expect(projectFromJson(projectToJson(song),loaded).wasOk()&&loaded.tracks[7].sampleRoot==57&&loaded.tracks[7].sampleTune==-23.5,"schema 15 round trips root and precise playback correction");
    for(int schema=1;schema<15;++schema){auto json=projectToJson(song);json.getDynamicObject()->setProperty("schema",schema);expect(projectFromJson(json,loaded).wasOk()&&loaded.tracks[7].sampleRoot==60&&loaded.tracks[7].sampleTune==0,"all older project schemas retain legacy sample mapping");}
    auto before=JSON::toString(projectToJson(loaded));for(auto invalid:{var(-1),var(128),var(60.5),var("60"),var(true),var()}){auto json=projectToJson(song);(*json["tracks"].getArray())[7].getDynamicObject()->setProperty("sampleRoot",invalid);expect(projectFromJson(json,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"invalid persisted root fails without replacing the project");}for(auto invalid:{var(-100.1),var(100.1),var("0"),var(true),var(std::nan(""))}){auto json=projectToJson(song);(*json["tracks"].getArray())[7].getDynamicObject()->setProperty("sampleTune",invalid);expect(projectFromJson(json,loaded).failed(),"invalid persisted tuning rejects");}
    auto missing=projectToJson(song);(*missing["tracks"].getArray())[7].getDynamicObject()->removeProperty("sampleRoot");expect(projectFromJson(missing,loaded).failed(),"new schema requires explicit sampler mapping");
    SamplePitch pitch;for(double rate:{8000.,44100.,48000.,96000.})for(double frequency:{55.,220.,440.,1046.502}){auto tone=tuningTone(rate,frequency,.75,true);auto result=detectSamplePitch(tone,rate,0,tone.getNumSamples(),pitch);expect(result.wasOk()&&std::abs(1200*std::log2(pitch.frequency/frequency))<5,"band-limited pitch detection follows low/high monophonic tones across source rates");}
    for(double frequency:{25.,3000.}){auto outside=tuningTone(48000,frequency);expect(detectSamplePitch(outside,48000,0,outside.getNumSamples(),pitch).failed(),"out-of-range pure tones do not fold into an in-range subharmonic");}
    auto sharp=tuningTone(48000,220*std::pow(2.,23.5/1200),1,true);expect(detectSamplePitch(sharp,48000,0,sharp.getNumSamples(),pitch).wasOk()&&pitch.root==57&&std::abs(pitch.cents+23.5)<1&&pitch.confidence>.9,"detector returns root and opposite cents correction for a sharp recording");
    auto flat=tuningTone(48000,440*std::pow(2.,-31./1200));expect(detectSamplePitch(flat,48000,0,flat.getNumSamples(),pitch).wasOk()&&pitch.root==69&&std::abs(pitch.cents-31)<1,"flat source gets positive playback correction");
    auto silent=tuningTone(48000,220);silent.clear();pitch={57,23,220,.9,2};auto unchanged=pitch;expect(detectSamplePitch(silent,48000,0,silent.getNumSamples(),pitch).failed()&&pitch.root==unchanged.root&&pitch.cents==unchanged.cents,"silent sample preserves detector output");for(int ch=0;ch<2;++ch)for(int i=0;i<silent.getNumSamples();++i)silent.setSample(ch,i,.3f);expect(detectSamplePitch(silent,48000,0,silent.getNumSamples(),pitch).failed(),"DC is not interpreted as a musical note");
    auto shortTone=tuningTone(48000,440,.05);expect(detectSamplePitch(shortTone,48000,0,shortTone.getNumSamples(),pitch).failed(),"short drum-like ranges require manual tuning");auto noise=tuningTone(48000,440);uint32_t seed=555;for(int ch=0;ch<2;++ch)for(int i=0;i<noise.getNumSamples();++i){seed=seed*1664525+1013904223;noise.setSample(ch,i,((int)(seed>>16)-32768)/65536.f);}expect(detectSamplePitch(noise,48000,0,noise.getNumSamples(),pitch).failed(),"unpitched noise rejects rather than proposing an arbitrary root");
    expect(detectSamplePitch(sharp,48000,0,sharp.getNumSamples(),pitch,[]{return true;}).failed(),"pitch detection supports cancellation before allocating audio");int polls=0;expect(detectSamplePitch(sharp,48000,0,sharp.getNumSamples(),pitch,[&]{return ++polls>12;}).failed(),"pitch detection supports cancellation during processing");
    expect(detectSamplePitch(sharp,48000,-1,1000,pitch).failed()&&detectSamplePitch(sharp,4000,0,1000,pitch).failed(),"invalid sample range or rate rejects");auto nonFinite=sharp;nonFinite.setSample(0,200,std::nanf(""));expect(detectSamplePitch(nonFinite,48000,0,nonFinite.getNumSamples(),pitch).failed(),"non-finite sample rejects pitch analysis");
    auto folder=root.getChildFile("sampler-tuning-core");folder.createDirectory();auto file=folder.getChildFile("A3-sharp.wav");{auto stream=file.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(format.createWriterFor(stream.get(),48000,2,24,{},0));if(writer){stream.release();writer->writeFromAudioSampleBuffer(sharp,0,sharp.getNumSamples());}}
    song=emptyProject();song.loop=false;auto& track=song.tracks[7];track.instrument=Instrument::sample;track.samplePath=file.getFullPathName();track.sampleRoot=57;track.sampleTune=-23.5;track.send=0;track.cutoff=20000;track.sampleLoop=true;song.patterns[0].lanes[7]={{0,2,60,.8f}};
    auto rendered=render(song,assets,folder,24000);expect(std::abs(tuningFrequency(rendered,48000)-261.625565)<.2,"C4 note on an aligned A3 sample produces audible C4");song.patterns[0].lanes[7][0].pitch=69;auto octave=render(song,assets,folder,24000,127);expect(std::abs(tuningFrequency(octave,48000)-440)<.2,"A4 note renders correct octave and corrected sample frequency");auto other=render(song,assets,folder,24000,512);expect(other==octave,"tuned sampler output stays independent of callback block size");
    auto target=folder.getChildFile("saved.pulse");expect(saveProject(song,target).wasOk()&&loadProject(target,loaded).wasOk()&&loaded.tracks[7].sampleRoot==57&&loaded.tracks[7].sampleTune==-23.5,"native save/load preserves sample root and cents");Project collected;expect(collectAssets(song,folder,folder.getChildFile("portable"),collected).wasOk()&&collected.tracks[7].sampleRoot==57&&collected.tracks[7].sampleTune==-23.5,"sample collection preserves tuning");
    auto legacy=projectToJson(song);legacy.getDynamicObject()->setProperty("schema",14);Project old;projectFromJson(legacy,old);auto standard=song;standard.masterSoftClip=true;standard.tracks[7].sampleRoot=60;standard.tracks[7].sampleTune=0;expect(render(old,assets,folder,8000)==render(standard,assets,folder,8000),"older schema migration preserves exact legacy sampler audio");
    song.bpm=120;song.patterns[0].lanes[7]={{0,4,60,.8f}};song.tracks[7].sampleStart=0;song.tracks[7].sampleEnd=.9;song.tracks[7].sampleLoop=false;
    auto chased=makeEngine(song,assets,folder);chased->seekRequested.store(.25);AudioBuffer<float> a(2,1024),b(2,1024);chased->render(a.getWritePointer(0),a.getWritePointer(1),1024);auto offset=song;double ratio=samplerRatio(60,57,-23.5);offset.tracks[7].sampleStart=.125*ratio;auto regular=makeEngine(offset,assets,folder);regular->render(b.getWritePointer(0),b.getWritePointer(1),1024);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<1024;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(chased->chasedNotes.load()==1&&difference<.00001f,"held-note chase uses root and fine tune when calculating source position");
    chased=makeEngine(song,assets,folder);chased->seekRequested.store(2.25);chased->render(a.getWritePointer(0),a.getWritePointer(1),1024);expect(chased->chasedNotes.load()==0&&a.getMagnitude(0,0,1024)==0,"tuned one-shot chase recognizes when resampling has exhausted the source");song.tracks[7].sampleLoop=true;chased=makeEngine(song,assets,folder);chased->seekRequested.store(2.25);chased->render(a.getWritePointer(0),a.getWritePointer(1),1024);offset=song;offset.tracks[7].sampleLoop=false;offset.tracks[7].sampleStart=std::fmod(1.125*ratio,.9);regular=makeEngine(offset,assets,folder);regular->render(b.getWritePointer(0),b.getWritePointer(1),1024);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<1024;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(chased->chasedNotes.load()==1&&difference<.00001f,"tuned loop chase wraps the corrected source position");
    ProjectTemplate savedTemplate;expect(saveProjectTemplate(song,folder,folder.getChildFile("Templates"),"Tuned sampler","Sampler calibration",TemplateContent::complete,savedTemplate).wasOk()&&loadProjectTemplate(savedTemplate,loaded).wasOk()&&loaded.tracks[7].sampleRoot==57&&loaded.tracks[7].sampleTune==-23.5,"project template saves calibrated sampler mapping");
    auto archive=folder.getChildFile("tuned.zip");File imported;expect(exportProjectArchive(song,folder,archive).wasOk()&&importProjectArchive(archive,folder.getNonexistentChildFile("Imported",String(),false),imported).wasOk()&&loadProject(imported,loaded).wasOk()&&loaded.tracks[7].sampleRoot==57&&loaded.tracks[7].sampleTune==-23.5,"portable project archive retains calibrated sampler mapping");
    auto ops=JSON::parse(R"([{"op":"set_track","track":7,"params":{"sampleRoot":69,"sampleTune":31.25}}])");Project edited;expect(applyControlEdits(song,ops,edited).wasOk()&&edited.tracks[7].sampleRoot==69&&edited.tracks[7].sampleTune==31.25,"MCP native edits accept root and fractional cents on a loaded sampler");auto stable=JSON::toString(projectToJson(edited));for(auto invalid:{R"([{"op":"set_track","track":7,"params":{"sampleRoot":60.5}}])",R"([{"op":"set_track","track":7,"params":{"sampleTune":101}}])"})expect(applyControlEdits(song,JSON::parse(invalid),edited).failed()&&JSON::toString(projectToJson(edited))==stable,"invalid MCP sampler tuning rejects atomically");
    auto playback=std::make_unique<Playback>();String warnings;song.tracks[7].sampleRoot=200;expect(compilePlayback(song,assets,folder,*playback,warnings).failed(),"playback compilation rejects invalid in-memory root values");auto bytes=target.loadFileAsString();expect(saveProject(song,target).failed()&&target.loadFileAsString()==bytes,"invalid sampler mapping cannot replace an existing saved project");
}
